+test_uncensored()
+
+// In general, the stacks a non-caller version of Error.captureStackStrace
+// should match what Error gives you
+function compare_stacks() {
+    function censor_column(str) {
+        return str.replace(/:(\d+):\d+\n/g, ":$1:censored\n")
+    }
