+function test_in_global(global) {
+    global.evaluate(caller.toString());
+    global.evaluate(fill.toString());
+    global.evaluate(test_elision.toString());
+    global.evaluate("test_elision()");
+
+    global.evaluate(nestedLambda.toString())
